mapper.insert:
insert into drive_upload_reservation (
    reservation_id, space_id, storage_key, reserved_bytes, status,
    expire_time, retry_count, next_retry_time, version,
    create_by, create_time, update_by, update_time, last_error_code
) values (
    #{reservationId}, #{spaceId}, #{storageKey}, #{reservedBytes}, #{status},
    #{expireTime}, #{retryCount}, #{nextRetryTime}, #{version},
    #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{lastErrorCode}
)

mapper.update:
update drive_upload_reservation
set status = 'CLEANING',
    version = version + 1,
    update_by = #{updateBy},
    update_time = #{now}
where reservation_id = #{reservationId}
  and version = #{version}
  and (
    (status = 'RESERVED' and expire_time <= #{now})
    or (status = 'CLEANUP_FAILED' and next_retry_time <= #{now})
    or (status = 'CLEANING' and update_time <= #{staleCleaningBefore})
  )

mapper.delete:
delete from drive_upload_reservation
where reservation_id = #{reservationId}
  and version = #{version}
  and status = #{status}
